import manifest from "@/data/responsive-images.json";

// Generated by scripts/build-responsive-images.mjs: "/public/path" -> [width, height, hash, variantWidths].
type Entry = [number, number, string, number[]];
const images = manifest as unknown as Record<string, Entry>;

export interface ResponsiveImageAttrs {
  src: string;
  srcSet?: string;
  sizes?: string;
  width?: number;
  height?: number;
}

const variantUrl = (key: string, hash: string, w: number) => {
  const slash = key.lastIndexOf("/");
  const dir = key.slice(0, slash);
  const name = key.slice(slash + 1).replace(/\.[^.]+$/, "").replace(/[^A-Za-z0-9._-]+/g, "-");
  return `/_img${dir}/${name}.${hash}.w${w}.webp`;
};

const lookup = (src: string): [string, Entry] | null => {
  if (!src || !src.startsWith("/")) return null;
  let key = src.split(/[?#]/)[0];
  try { key = decodeURI(key); } catch { /* keep as-is */ }
  const entry = images[key];
  return entry ? [key, entry] : null;
};

/**
 * Attributes for a responsive <img> (or motion.img): build-time WebP variants via srcSet, the intrinsic
 * width/height (prevents layout shift; CSS still controls the rendered size) and the caller's `sizes`.
 * Sources outside public/ (external URLs) or not yet processed fall back to the original src unchanged.
 */
export function responsiveImage(src: string, sizes: string): ResponsiveImageAttrs {
  const hit = lookup(src);
  if (!hit) return { src };
  const [key, [width, height, hash, widths]] = hit;
  const srcSet = widths.map((w) => `${variantUrl(key, hash, w)} ${w}w`).join(", ");
  // Fallback src (browsers without srcset support never pick it otherwise): the variant closest to 1200px.
  const fallback = widths.reduce((best, w) => (Math.abs(w - 1200) < Math.abs(best - 1200) ? w : best), widths[0]);
  return { src: variantUrl(key, hash, fallback), srcSet, sizes, width, height };
}

/** Intrinsic size of a public/ image, when known. */
export function imageSize(src: string): { width: number; height: number } | null {
  const hit = lookup(src);
  return hit ? { width: hit[1][0], height: hit[1][1] } : null;
}

/** All generated variants of a public/ image as { width, url }, smallest first (e.g. for WebGL textures). */
export function imageVariants(src: string): { width: number; url: string }[] {
  const hit = lookup(src);
  if (!hit) return [];
  const [key, [, , hash, widths]] = hit;
  return widths.map((w) => ({ width: w, url: variantUrl(key, hash, w) }));
}
